import os
import pprint
import re
protocols = {'5G': 'nsetap-x', '4G': 'nsetap'}
protocols_standard_filename = {'nsetap-x': 'nsetap-x.txt', 'nsetap': 'nsetap.txt'}
#   nsetap-x - https://svne1.access.nsn.com/isource/svnroot/BTS_I_NSETAP-X/trunk/
#   nsetap - https://svne1.access.nsn.com/isource/svnroot/BTS_I_NSETAP/trunk/nsetap/
DOC_TEMPLATE_START = "<DOC_TEMPLATE>"
DOC_TEMPLATE_END = "</DOC_TEMPLATE>"


def find_vendor_payloads(standard, protocol_version):
    if 'nsetap-x' == protocol_version:
        return re.findall(r'-- carries\s(\S+)', standard)
    else:
        return [item for item in re.findall(r'(\S+)\s+::\=\s+CHOICE ', standard) if 'ExtensionRecord' in item]


def find_vendor_payload_record(vendor_payload, content):
    records = []
    regexp = "{}".format(vendor_payload) + r"\s::=\sCHOICE\s\{(.*?)\}"
    records_section = re.findall(regexp, content, re.MULTILINE | re.DOTALL)[0]
    # print(records_section)
    for record_section_line in records_section.split(','):
        # print("$"+record_section_line+"#")
        result = re.findall(r'\s*(\S+)\s+(\S+)\s*', record_section_line.strip(), re.MULTILINE | re.DOTALL)
        if len(result):
            records.append({'record_visible_name': result[0][0], 'record_type_name': result[0][1]})
    # print(records)
    return records


def read_protocol_standard(protocol):
    curr_file_dir = os.path.dirname(os.path.abspath(__file__))
    protocol_file_dir = os.path.join(curr_file_dir, protocols_standard_filename[protocol])
    assert os.path.exists(protocol_file_dir), 'File: {} not found'.format(protocol_file_dir)
    with open(protocol_file_dir, 'r') as file:
        content = file.read()
    return content


def get_pcmd_protocol_data(technology, flat=False):
    """
    returns:
        if flat = True
            [{'record_type_name':x, 'record_visible_name': y}, ...]
        of flat is False
            { 'extRecordClass1' :
                        [ {'record_type_name':x, 'record_visible_name': y},
                        ...
                        ],
             'extRecordClass2':
                        [ {'record_type_name':x1, 'record_visible_name': y1},
                        ...
                        ],
            ...
            }
    """
    assert technology in protocols, 'Technology not found in implemented: {}'.format(protocols.keys())
    protocol_version = protocols[technology]
    protocol_data = {}
    content = read_protocol_standard(protocol_version)
    vendor_payloads = find_vendor_payloads(content, protocol_version)
    # print(vendor_payloads)
    for vendor_payload in vendor_payloads:
        records = find_vendor_payload_record(vendor_payload, content)
        protocol_data[vendor_payload] = records
    if flat is False:
        ret = protocol_data
    else:
        ret = sum([protocol_data[record_name] for record_name in protocol_data.keys()], [])
    pprint.pprint(ret)
    return ret


def get_record_names_for_documentation():
    fiveG_records = get_pcmd_protocol_data('5G', True)
    fourG_records = get_pcmd_protocol_data('4G', True)
    string_for_doc = \
        "{}\n" \
        "  5G:\n" \
        "{}\n" \
        "        \n" \
        "  4G:\n" \
        "{}\n" \
        "{}"
    fiveG_records_string = "\n".join(["        {}".format(fiveG_record['record_type_name'])
                                      for fiveG_record in fiveG_records])
    fourG_records_string = "\n".join(["        {}".format(fourG_record['record_type_name'])
                                      for fourG_record in fourG_records])
    string_for_doc = string_for_doc.format(DOC_TEMPLATE_START,
                                           fiveG_records_string,
                                           fourG_records_string,
                                           DOC_TEMPLATE_END)
    print(string_for_doc)
    return string_for_doc


if __name__ == "__main__":
    # get_record_names_for_documentation()
    # print("\n".join([item['record_type_name'] for item in get_pcmd_protocol_data('5G', True)]))
    # print("\n".join([item['record_type_name'] for item in get_pcmd_protocol_data('4G', True)]))
    record_names = get_pcmd_protocol_data('5G', False)
    # dict((item['record_visible_name'], item['record_type_name'])
    asn1_supported_record_name_to_type = {}
    for vendor_name in record_names:
        asn1_supported_record_name_to_type[vendor_name] = {}
        for item in record_names[vendor_name]:
            asn1_supported_record_name_to_type[vendor_name][item['record_visible_name']] = item['record_type_name']
    pprint.pprint(asn1_supported_record_name_to_type)
    print([item for vendor in asn1_supported_record_name_to_type
           for item in asn1_supported_record_name_to_type[vendor]])
    get_record_names_for_documentation()
